        CAST(CASE WHEN EXISTS (SELECT 1 FROM [${flyway:defaultSchema}].[AIAgentRunStep] WHERE [ParentID] = @RecordID) THEN 0 ELSE 1 END AS BIT) AS [IsLeaf],
